Repository: tiangolo/fastapi
Issue: #829
Title: OpenAPI routes do not acknowledge root_path

Recently ran into this issue and the best solution I could think of was monkey patching `openapi.json`:

```python
app = FastAPI(
    title=settings.PROJECT_NAME,
    description=settings.PROJECT_DESCRIPTION,
    version=settings.PROJECT_VERSION,
    openapi_url=None,
    openapi_tags=openapi_tags,
    docs_url=None,
    redoc_url=None,
    root_path=settings.ROOT_PATH,
)

@app.get("/", include_in_schema=False)
async def access_documentation():
    openapi_url = app.root_path + "/openapi.json"
    return get_swagger_ui_html(openapi_url=openapi_url, title="docs")

@app.get("/openapi.json", include_in_schema=False)
async def access_openapi():
    openapi = get_openapi(
        title=app.title,
        version=app.version,
        description=app.description,
        routes=app.routes,
        tags=app.openapi_tags,
    )

    monkey_patched_openapi = {
        key: value for key, value in openapi.items() if key != "paths"
    }
    monkey_patched_openapi["paths"] = {}
    for key, value in openapi["paths"].items():
        monkey_patched_openapi["paths"][app.root_path + key] = value

    return monkey_patched_openapi
```

Not elegant, but this did exactly what I was looking for: serving my API at `/api/v1/` with swaggerui working as expected.

Edit: I had to declare separate openapi functions because I wanted to protected them using basic auth, which is not used for anything else in the app (dependencies not shown above for clarity).

FYI, I'm running behind NGINX in docker-compose which looks like this:

```
events {}

http {
    upstream backend_server {
        server api:80;
    }

    server {
        listen 80;

        location /api/v1/ {
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_pass http://backend_server/;
        }
    }
}
```

Edit 2: the above can be achieved in a simpler way with a downside (or upside) of the "servers" drop-down appearing and the `/api/v1` prefix disappearing:

```python
@app.get("/openapi.json", include_in_schema=False)
async def access_openapi():
    openapi = get_openapi(
        title=app.title,
        version=app.version,
        description=app.description,
        routes=app.routes,
        tags=app.openapi_tags,
    )
    openapi["servers"] = [{"url": app.root_path}]
    return openapi
```

Repository: pydantic/pydantic
Issue: #1279
Title: Read values from secrets files when using BaseSettings

I took a slightly different approach and implemented it as a subclass that my settings classes can then subclass themselves.

```py
from pathlib import Path
from typing import Dict, Optional, Union

from pydantic.env_settings import BaseSettings, SettingsError


class SecretsSettings(BaseSettings):
    """Settings model that additionally reads values from a secrets directory.

    Configurable through Config.secrets_path, defaults to "/run/secrets".
    """

    def __init__(__pydantic_self__, *args, _secrets_path: Union[str, Path, None] = None, **kwargs):
        secrets_path = _secrets_path or __pydantic_self__.__config__.secrets_path
        if secrets_path is not None:
            path = Path(secrets_path).expanduser()
            secrets_dict = __pydantic_self__._scan_secrets_dir(path)
            kwargs = {**secrets_dict, **kwargs}
        # Currently, secrets override values from env
        super().__init__(*args, **kwargs)

    def _scan_secrets_dir(self, secrets_path: Path) -> Dict[str, str]:
        d: Dict[str, str] = {}

        if not secrets_path.is_dir():
            return d

        secret_paths = {
            (item.name if self.__config__.case_sensitive else item.name.lower()): item
            for item in secrets_path.iterdir()
            if item.is_file()
        }

        for field in self.__fields__.values():
            value: Optional[str] = None
            for env_name in field.field_info.extra['env_names']:
                if path := secret_paths.get(env_name):
                    if (value := path.read_text().strip()) is not None:
                        break
            else:
                continue

            if field.is_complex():
                try:
                    value = self.__config__.json_loads(value)  # type: ignore
                except ValueError as e:
                    raise SettingsError(f'error parsing JSON for "{env_name}"') from e

            if value is not None:
                d[field.alias] = value

        return d

    class Config:
        secrets_path = "/run/secrets"


class TestSettings(SecretsSettings):
    password: str

    class Config:
        env_prefix = "test_"

# reads from "/run/secrets/test_password"
print(TestSettings().password)
assert TestSettings(password="abc").password == "abc"
```

I can submit this as a PR, if desired. I only need to know whether the default class should be extended with this and whether environment variables or secrets should take priority.
(And I should probably be using `deep_update` for the kwargs, but this fulfills my needs.)

